class Solution {
public:
    std::vector<std::string> twoEditWords(std::vector<std::string>& queries, std::vector<std::string>& dictionary) {
        std::vector<std::string> ans;
        for (const auto& q : queries) {
            for (const auto& d : dictionary) {
                int diff = 0;
                for (size_t i = 0; i < q.size(); ++i) {
                    if (q[i] != d[i]) {
                        diff++;
                        if (diff > 2) break;
                    }
                }
                if (diff <= 2) {
                    ans.push_back(q);
                    break;
                }
            }
        }
        return ans;
    }
};

class Solution {
    public java.util.List<String> twoEditWords(String[] queries, String[] dictionary) {
        java.util.List<String> ans = new java.util.ArrayList<>();
        for (String q : queries) {
            for (String d : dictionary) {
                int diff = 0;
                for (int i = 0; i < q.length(); i++) {
                    if (q.charAt(i) != d.charAt(i)) {
                        diff++;
                        if (diff > 2) break;
                    }
                }
                if (diff <= 2) {
                    ans.add(q);
                    break;
                }
            }
        }
        return ans;
    }
}

var twoEditWords = function(queries, dictionary) {
    const ans = [];
    for (const q of queries) {
        for (const d of dictionary) {
            let diff = 0;
            for (let i = 0; i < q.length; i++) {
                if (q[i] !== d[i]) {
                    diff++;
                    if (diff > 2) break;
                }
            }
            if (diff <= 2) {
                ans.push(q);
                break;
            }
        }
    }
    return ans;
};
